#!/bin/bash
# Differential test for the consistency-based strategies: run the C `tbfast`
# and `tbfast-rs` on the same inputs with the same arguments and require every
# output file they produce (`pre`, `order`, `hat2`, `hat3`) to be byte-identical.
#
#   verify_tbfast.sh <path-to-C-tbfast> <path-to-rust-tbfast-rs> [corpus-dir]
#
# With no corpus directory, the corpus generated by verify.sh is reused.

set -u
CBIN="${1:?usage: verify_tbfast.sh <c-tbfast> <rust-tbfast-rs> [corpus-dir]}"
RBIN="${2:?usage: verify_tbfast.sh <c-tbfast> <rust-tbfast-rs> [corpus-dir]}"
CORPUS="${3:-}"

# Resolve the binaries to absolute paths and check they are runnable. Every
# comparison below runs from a scratch directory, so a relative path would not
# resolve -- and if *both* binaries fail to launch the run looks like a pass,
# which is how this harness once reported thousands of identical results while
# testing nothing at all.
abspath() {
  case "$1" in
    /*) printf '%s\n' "$1" ;;
    *)  printf '%s/%s\n' "$(pwd)" "$1" ;;
  esac
}
CBIN=$(abspath "$CBIN")
RBIN=$(abspath "$RBIN")
for b in "$CBIN" "$RBIN"; do
  if [ ! -x "$b" ]; then
    echo "verify: $b is not executable" 1>&2
    exit 2
  fi
done

here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# The argument vectors the mafft wrapper produces. `_ ... _` delimits the
# pairwise stage's options from the progressive stage's.
P="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.100 -f -2.00 -Q 100.0 -h 0.1"
PG="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.10 -f -2.00 -Q 100.0 -h 0.1"
T="-W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1"
# E-INS-i (--genafpair): the generalised affine-gap aligner, with -Z so the
# score comes from naivepairscore11; --oldgenafpair is the same without -Z.
PE="-u 0.0 -l 2.7 -C 0 -b 62 -g 0.0 -f -2.00 -Q 100.0 -h 0.0 -O -6.00 -E -0.000 -N -Z"
PEO="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.100 -f -2.00 -Q 100.0 -h 0.1 -O -6.00 -E -0.000 -N"
TE="-W 0.00001 -V -1.53 -s 0.0 -O -C 0 -b 62 -f -1.53 -Q 100.0 -h 0.000 -F -l 2.7 -X 0.1"

ARGSETS=(
  # L-INS-1 / L-INS-i  (--localpair)
  "_ $P -L _ -+ 0 $T -O"
  "_ $P -L _ -+ 2 $T -O"
  "_ $P -L _ -+ 16 $T -O"
  # G-INS-1 / G-INS-i  (--globalpair); no -O, so terminal gaps are charged
  "_ $PG -A _ -+ 0 $T"
  "_ $PG -A _ -+ 2 $T"
  # --allowshift: turns on the warp DP and the per-node dynamic matrix
  "_ -u 0.8 -l 2.7 -C 0 -b 62 -: -g 0 -f -2.00 -Q 2.00 -h 0 -A _ -+ 16 -W 0.00001 -V -1.53 -s 0.8 -C 0 -b 62 -: -f -1.53 -Q 2.00 -h 0 -F -l 2.7 -X 0.1"
  "_ -u 0.8 -l 2.7 -C 0 -b 62 -: -g 0 -f -2.00 -Q 2.00 -h 0 -L _ -+ 16 -W 0.00001 -V -1.53 -s 0.8 -C 0 -b 62 -: -f -1.53 -Q 2.00 -h 0 -O -F -l 2.7 -X 0.1"
  # non-default constraint weight and tree parameters
  "_ $P -L _ -+ 2 -W 0.001 -V -1.53 -s 0.0 -C 0 -b 62 -f -2.00 -Q 100.0 -h -0.1 -F -l 0.5 -X 0.5 -O"
  "_ $PG -A _ -+ 2 -W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -f -1.53 -Q 100.0 -h 0 -F -l 5.0 -X 0.0"
  # E-INS-1 / E-INS-i (--genafpair), and --oldgenafpair, which drops -Z and so
  # takes the branch with the X-stripped rescore and the dynamic matrix
  "_ $PE _ -+ 0 $TE"
  "_ $PE _ -+ 2 $TE"
  "_ $PEO _ -+ 0 $TE"
  # -t (tree output) and -T (noalign), whose exits sit either side of the
  # pairwise stage
  "_ $P -L _ -+ 0 $T -O -t"
  "_ $P -L _ -+ 2 $T -O -t -T"
  "_ $P -L _ -+ 0 $T -O -T"
  "_ $P -L _ -+ 2 $T -O -^"
  # --legacygapcost in the progressive stage
  "_ $P -L _ -+ 2 -W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -L -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1 -O"
  # --fmodel and JTT on both stages
  "_ -u 0.0 -l 2.7 -C 0 -j 200 -a -g -0.100 -f -2.00 -Q 100.0 -h 0.1 -L _ -+ 2 -W 0.00001 -V -1.53 -s 0.0 -C 0 -j 200 -a -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1 -O"
  # a non-default BLOSUM table on both stages
  "_ -u 0.0 -l 2.7 -C 0 -b 80 -g -0.100 -f -2.00 -Q 100.0 -h 0.1 -L _ -+ 2 -W 0.00001 -V -1.53 -s 0.0 -C 0 -b 80 -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1 -O"
)

if [ -z "$CORPUS" ]; then
  CORPUS="$work/corpus"
  mkdir -p "$CORPUS"
  cp "$here/../test/sample" "$CORPUS/sample.fa"
  cp "$here/../test/samplerna" "$CORPUS/samplerna.fa"
  python3 "$here/gencorpus.py" "$here/../test/sample" "$CORPUS" small
fi

# An empty or missing corpus would make every loop below run zero times and
# report a clean pass. Refuse instead -- this harness has been vacuous once
# already (see the abspath check above).
n_corpus=$(find "$CORPUS" -maxdepth 1 -type f | wc -l)
if [ "$n_corpus" -lt 10 ]; then
  echo "verify: corpus at $CORPUS has only $n_corpus files; refusing to run" 1>&2
  exit 2
fi

pass=0; fail=0; failed=""
for f in "$CORPUS"/*; do
  [ -f "$f" ] || continue
  for i in "${!ARGSETS[@]}"; do
    args="${ARGSETS[$i]}"
    rm -rf "$work/c" "$work/r"
    mkdir -p "$work/c" "$work/r"
    ( cd "$work/c" && $CBIN $args < "$f" > /dev/null 2> err.log )
    cst=$?
    ( cd "$work/r" && $RBIN $args < "$f" > /dev/null 2> err.log )
    rst=$?
    label="$(basename "$f") [argset $i]"
    if [ $cst -ne $rst ]; then
      fail=$((fail+1)); failed="$failed\n  $label (exit $cst vs $rst)"
      continue
    fi
    bad=""
    for out in pre order hat2 hat3 infile.tree; do
      if [ -f "$work/c/$out" ] || [ -f "$work/r/$out" ]; then
        cmp -s "$work/c/$out" "$work/r/$out" || bad="$bad $out"
      fi
    done
    if [ -n "$bad" ]; then
      fail=$((fail+1)); failed="$failed\n  $label (differs:$bad)"
    else
      pass=$((pass+1))
    fi
  done
done

# --treein (-U): a user guide tree read from `_guidetree`, which means no
# distance matrix or all-pairs stage feeding it. The tree must match the input's sequence
# count, so it is generated per input rather than being an ARGSETS entry.
P="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.100 -f -2.00 -Q 100.0 -h 0.1 -L"
T="-W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1 -O"
for f in "$CORPUS"/*; do
  [ -f "$f" ] || continue
  n=$(grep -c '^>' "$f")
  [ "$n" -ge 2 ] || continue
  for shape in ladder balanced; do
    for extra in "" "-t"; do
      rm -rf "$work/c" "$work/r"
      mkdir -p "$work/c" "$work/r"
      python3 "$here/gen_treein.py" "$n" "$shape" > "$work/c/_guidetree"
      cp "$work/c/_guidetree" "$work/r/_guidetree"
      ( cd "$work/c" && $CBIN _ $P _ -+ 2 $T -U $extra < "$f" > /dev/null 2> err.log )
      cst=$?
      ( cd "$work/r" && $RBIN _ $P _ -+ 2 $T -U $extra < "$f" > /dev/null 2> err.log )
      rst=$?
      label="$(basename "$f") [-U $shape $extra]"
      if [ $cst -ne $rst ]; then
        fail=$((fail+1)); failed="$failed\n  $label (exit $cst vs $rst)"
        continue
      fi
      bad=""
      for o in pre order hat2 hat3 infile.tree; do
        if [ -f "$work/c/$o" ] || [ -f "$work/r/$o" ]; then
          cmp -s "$work/c/$o" "$work/r/$o" || bad="$bad $o"
        fi
      done
      if [ -n "$bad" ]; then
        fail=$((fail+1)); failed="$failed\n  $label (differs:$bad)"
      else
        pass=$((pass+1))
      fi
    done
  done
done

# --aamatrix (-b -1): the scoring matrix comes from `_aamtx`. Both phases get
# it, so the pairwise stage and the progressive stage are both covered.
for f in "$CORPUS"/*; do
  [ -f "$f" ] || continue
  for variant in plain perm norescale permfreq; do
    rm -rf "$work/c" "$work/r"
    mkdir -p "$work/c" "$work/r"
    python3 "$here/gen_aamtx.py" "$variant" > "$work/c/_aamtx" || continue
    cp "$work/c/_aamtx" "$work/r/_aamtx"
    MP="-u 0.0 -l 2.7 -C 0 -b -1 -g -0.100 -f -2.00 -Q 100.0 -h 0.1 -L"
    MT="-W 0.00001 -V -1.53 -s 0.0 -C 0 -b -1 -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1 -O"
    ( cd "$work/c" && $CBIN _ $MP _ -+ 2 $MT < "$f" > /dev/null 2> err.log )
    cst=$?
    ( cd "$work/r" && $RBIN _ $MP _ -+ 2 $MT < "$f" > /dev/null 2> err.log )
    rst=$?
    label="$(basename "$f") [--aamatrix $variant]"
    if [ $cst -ne $rst ]; then
      fail=$((fail+1)); failed="$failed\n  $label (exit $cst vs $rst)"
      continue
    fi
    bad=""
    for o in pre order hat2 hat3; do
      if [ -f "$work/c/$o" ] || [ -f "$work/r/$o" ]; then
        cmp -s "$work/c/$o" "$work/r/$o" || bad="$bad $o"
      fi
    done
    if [ -n "$bad" ]; then
      fail=$((fail+1)); failed="$failed\n  $label (differs:$bad)"
    else
      pass=$((pass+1))
    fi
  done
done

# --add / --addprofile (-I n, -K) and --keeplength (-Y) with both --mapout
# forms. Needs a real alignment to add to, so the C is run once to make one.
# `disttbfast` builds it: tbfast writes `pre`, not stdout.
DTB="$(dirname "$CBIN")/disttbfast"
if [ -x "$DTB" ]; then
AARGS="-q 0 -E 2 -V -1.53 -s 0.0 -W 6 -O -C 0-0 -b 62 -g 0 -f -1.53 -Q 100.0 -h 0 -F -X 0.1 -x 100"
for f in "$CORPUS"/*; do
  [ -f "$f" ] || continue
  n=$(grep -c '^>' "$f")
  [ "$n" -ge 4 ] || continue
  rm -rf "$work/pre"; mkdir -p "$work/pre"
  ( cd "$work/pre" && $DTB $AARGS < "$f" > aligned.fa 2> /dev/null ) || continue
  [ -s "$work/pre/aligned.fa" ] || continue
  for nadd in 1 $((n/2)); do
    for mode in add profile; do
      python3 "$here/gen_add.py" "$work/pre/aligned.fa" "$nadd" "$mode" > "$work/pre/in.fa" || continue
      kflag=""
      [ "$mode" = "add" ] && kflag="-K"
      for extra in "" "-Y" "-Y -Z" "-Y -z"; do
        rm -rf "$work/c" "$work/r"
        mkdir -p "$work/c" "$work/r"
        ( cd "$work/c" && $CBIN _ $P _ -+ 2 $T -I $nadd $kflag $extra < "$work/pre/in.fa" > /dev/null 2> err.log )
        cst=$?
        ( cd "$work/r" && $RBIN _ $P _ -+ 2 $T -I $nadd $kflag $extra < "$work/pre/in.fa" > /dev/null 2> err.log )
        rst=$?
        label="$(basename "$f") [-I $nadd $mode $extra]"
        if [ $cst -ne $rst ]; then
          fail=$((fail+1)); failed="$failed\n  $label (exit $cst vs $rst)"
          continue
        fi
        bad=""
        for o in pre order hat2 hat3 _deletelist _deletemap; do
          if [ -f "$work/c/$o" ] || [ -f "$work/r/$o" ]; then
            cmp -s "$work/c/$o" "$work/r/$o" || bad="$bad $o"
          fi
        done
        if [ -n "$bad" ]; then
          fail=$((fail+1)); failed="$failed\n  $label (differs:$bad)"
        else
          pass=$((pass+1))
        fi
      done
    done
  done
done
fi

echo "pass=$pass fail=$fail"
if [ $fail -ne 0 ]; then
  printf 'FAILED:%b\n' "$failed"
  exit 1
fi
